create table TB_CASH_JOURNAL (JOURNAL_ID VARCHAR(60) not null  ,CHANNEL_SEQ_NO VARCHAR(60) null  ,SUB_SEQ_NO VARCHAR(60) null  ,TAE_SEQ_NO VARCHAR(60) null  ,REFERENCE VARCHAR(60) null  ,MOVE_ID VARCHAR(30) null  ,MOVE_TYPE VARCHAR(3) null  ,TRAN_DATE TIMESTAMP(3) not null  ,TRAN_BRANCH VARCHAR(30) null  ,USER_ID VARCHAR(30) null  ,SOURCE_TYPE VARCHAR(10) null  ,SOURCE_MODULE VARCHAR(2) null  ,TAILBOX_ID VARCHAR(30) null  ,TAILBOX_USER_ID VARCHAR(30) null  ,CCY VARCHAR(3) null  ,CASH_NUM INT null  ,TRAN_AMT DECIMAL(17,2) null  ,ACTUAL_AMT DECIMAL(17,2) null  ,PAY_REC VARCHAR(2) null  ,PROGRAM_ID VARCHAR(50) null  ,TRAN_DESC VARCHAR(200) null  ,REMARK VARCHAR(200) null  ,APPR_USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,RESERVE_FLAG VARCHAR(1) null  ,TO_BRANCH VARCHAR(30) null  ,TO_USER_ID VARCHAR(30) null  ,TO_TAILBOX_ID VARCHAR(30) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(JOURNAL_ID,TRAN_DATE));